
import argparse
import json
import subprocess
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent
SCRIPTS_DIR = PROJECT_ROOT / "scripts"

sys.path.insert(0, str(PROJECT_ROOT))

from src.monitoring.logger import PipelineMonitor


def load_json_report(project_root, relative_path):
    """Load a JSON report generated by a completed pipeline stage."""

    report_path = project_root / relative_path

    if not report_path.exists():
        raise FileNotFoundError(
            f"Expected pipeline report not found: {report_path}"
        )

    with open(report_path, "r", encoding="utf-8") as file:
        return json.load(file)


def collect_pipeline_metrics(project_root):
    """Collect business metrics from completed pipeline reports."""

    validation = load_json_report(
        project_root,
        "outputs/validation_report.json",
    )

    identity = load_json_report(
        project_root,
        "outputs/identity_resolution_report.json",
    )

    customer_360 = load_json_report(
        project_root,
        "outputs/customer_360_metrics.json",
    )

    publishing = load_json_report(
        project_root,
        "outputs/publishing_report.json",
    )

    return {
        "validation": {
            "datasets": validation["datasets"],
            "total_input_rows": (
                validation["summary"]["total_input_rows"]
            ),
            "total_valid_rows": (
                validation["summary"]["total_valid_rows"]
            ),
            "total_quarantined_rows": (
                validation["summary"]["total_quarantined_rows"]
            ),
            "overall_success_rate_percent": (
                validation["summary"][
                    "overall_success_rate_percent"
                ]
            ),
        },
        "identity_resolution": identity,
        "customer_360": customer_360,
        "publishing": {
            "database": publishing["database"],
            "datasets": {
                name: {
                    "row_count": details["row_count"],
                    "parquet_file": details["parquet_file"],
                }
                for name, details in publishing[
                    "datasets"
                ].items()
            },
        },
    }


def run_stage(
    stage_name,
    script_name,
    monitor,
    extra_args=None,
    retries=2,
    retry_delay_seconds=2.0,
):
    """Execute a pipeline stage with retries and monitoring."""

    script_path = SCRIPTS_DIR / script_name

    if not script_path.exists():
        raise FileNotFoundError(
            f"Pipeline script not found: {script_path}"
        )

    command = [
        sys.executable,
        str(script_path),
    ]

    if extra_args:
        command.extend(extra_args)

    max_attempts = retries + 1

    print(f"\n{'=' * 60}", flush=True)
    print(f"STARTING: {stage_name}", flush=True)
    print(f"{'=' * 60}", flush=True)

    stage_record = monitor.start_stage(stage_name)
    started = time.perf_counter()

    for attempt in range(1, max_attempts + 1):

        print(
            f"Attempt {attempt}/{max_attempts}: {stage_name}",
            flush=True,
        )

        try:
            subprocess.run(
                command,
                cwd=PROJECT_ROOT,
                check=True,
            )

            elapsed = time.perf_counter() - started

            monitor.complete_stage(
                stage_record,
                elapsed,
            )

            print(
                f"COMPLETED: {stage_name} "
                f"in {elapsed:.2f} seconds",
                flush=True,
            )

            return elapsed

        except Exception as error:

            if attempt < max_attempts:
                message = (
                    f"{stage_name} failed on attempt "
                    f"{attempt}/{max_attempts}: {error}. "
                    f"Retrying in {retry_delay_seconds} seconds."
                )

                monitor.log(
                    message,
                    level="WARNING",
                )

                print(
                    message,
                    file=sys.stderr,
                    flush=True,
                )

                time.sleep(retry_delay_seconds)

            else:
                elapsed = time.perf_counter() - started

                monitor.fail_stage(
                    stage_record,
                    error,
                )

                print(
                    f"FAILED: {stage_name} after "
                    f"{max_attempts} attempts "
                    f"and {elapsed:.2f} seconds",
                    file=sys.stderr,
                    flush=True,
                )

                raise


def main():
    parser = argparse.ArgumentParser(
        description="Customer 360 Data Engineering Pipeline"
    )

    parser.add_argument(
        "--customers",
        type=int,
        default=1000,
        help="Number of synthetic customers",
    )

    parser.add_argument(
        "--seed",
        type=int,
        default=42,
        help="Random seed",
    )

    parser.add_argument(
        "--retries",
        type=int,
        default=2,
        help="Number of retries after the initial stage attempt",
    )

    parser.add_argument(
        "--retry-delay",
        type=float,
        default=2.0,
        help="Delay in seconds between retry attempts",
    )

    args = parser.parse_args()

    if args.customers < 1:
        parser.error("--customers must be at least 1")

    if args.retries < 0:
        parser.error("--retries cannot be negative")

    if args.retry_delay < 0:
        parser.error("--retry-delay cannot be negative")

    monitor = PipelineMonitor(PROJECT_ROOT)

    stage_timings = {}

    stages = [
        (
            "Synthetic Data Generation",
            "generate_data.py",
            [
                "--customers",
                str(args.customers),
                "--seed",
                str(args.seed),
            ],
        ),
        (
            "Data Validation",
            "validate_data.py",
            None,
        ),
        (
            "Customer Identity Resolution",
            "resolve_identities.py",
            None,
        ),
        (
            "Customer 360 Transformation",
            "build_customer_360.py",
            None,
        ),
        (
            "Data Publishing (Parquet + DuckDB)",
            "publish_data.py",
            None,
        ),
    ]

    print("\nCUSTOMER 360 DATA ENGINEERING PIPELINE")
    print("Run ID:", monitor.run_id)
    print("Project:", PROJECT_ROOT)
    print("Customers requested:", args.customers)
    print("Random seed:", args.seed)
    print("Maximum retries per stage:", args.retries)
    print("Retry delay:", args.retry_delay, "seconds")

    # Execute pipeline stages.
    try:
        for stage_name, script_name, extra_args in stages:

            elapsed = run_stage(
                stage_name=stage_name,
                script_name=script_name,
                monitor=monitor,
                extra_args=extra_args,
                retries=args.retries,
                retry_delay_seconds=args.retry_delay,
            )

            stage_timings[stage_name] = round(
                elapsed,
                3,
            )

    except Exception as error:
        print(
            f"\nPIPELINE FAILED: {error}",
            file=sys.stderr,
            flush=True,
        )

        monitor.finish("FAILED")
        sys.exit(1)

    # Collect metrics after all stages succeed.
    try:
        metrics = collect_pipeline_metrics(PROJECT_ROOT)

        monitor.set_metrics(metrics)

        print("\nPIPELINE BUSINESS METRICS COLLECTED")

        print(
            "Validation success rate:",
            metrics["validation"][
                "overall_success_rate_percent"
            ],
            "%",
        )

        print(
            "Golden customers:",
            metrics["identity_resolution"][
                "golden_customers"
            ],
        )

        print(
            "Published datasets:",
            len(metrics["publishing"]["datasets"]),
        )

    except Exception as error:
        print(
            f"\nMETRICS COLLECTION FAILED: {error}",
            file=sys.stderr,
            flush=True,
        )

        monitor.log(
            f"Metrics collection failed: {error}",
            level="ERROR",
        )

        monitor.finish("FAILED")
        sys.exit(1)

    # Persist the successful pipeline run.
    run_record = monitor.finish("SUCCESS")

    print("\n" + "=" * 60)
    print("PIPELINE STAGE TIMINGS")
    print("=" * 60)

    for stage_name, elapsed in stage_timings.items():
        print(
            f"{stage_name}: {elapsed:.2f} seconds"
        )

    print(
        "\nCUSTOMER 360 PIPELINE COMPLETED SUCCESSFULLY"
    )

    print(
        "Total execution time:",
        run_record["total_duration_seconds"],
        "seconds",
    )

    print("\nMonitoring outputs:")
    print("logs/pipeline.log")
    print("outputs/pipeline_run_history.json")

    print("\nPublished outputs:")
    print("data/processed/customer_360.csv")
    print("data/processed/customer360.duckdb")
    print("data/processed/parquet/")


if __name__ == "__main__":
    main()
